package cn.iocoder.yudao.module.platform.api.sms;import cn.iocoder.yudao.module.platform.api.sms.dto.channel.SmsChannelRespDTO;import cn.iocoder.yudao.module.platform.convert.sms.SmsChannelConvert;import cn.iocoder.yudao.module.platform.service.sms.PlatformSmsChannelService;import org.springframework.stereotype.Service;import javax.annotation.Resource;import java.util.List;/** * 短信渠道API接口实现 * * @author zhusy * @since 2022/8/7 */@Servicepublic class SmsChannelApiImpl implements SmsChannelApi {    @Resource    private PlatformSmsChannelService platformSmsChannelService;    @Override    public List<SmsChannelRespDTO> getSmsChannelList() {        return SmsChannelConvert.INSTANCE.convertDTOList(platformSmsChannelService.getSmsChannelList());    }}